import sys

def main():
	for line in sys.stdin:
		f = int(line.strip())
		while f > 0:
			n = 0
			count1 = 0
			count2 = 0
			count = 0
			sum = 0
			flag = 0
			tempcount = 0
			(s, n) = input().split()
			n = int(n)
			for i in range(n):
				tempcount = 0
				for j in range(len(s)):
					if s[j] == 'a':
						count1 += 1
					elif s[j] == 'b':
						count2 += 1
					if count1 > count2:
						count += 1
						tempcount += 1
				if count1 == count2:
					flag = 1
					break
				if tempcount == len(s):
					flag = 2
					break
				if tempcount == 0:
					break
			if flag == 1:
				sum = count * n
			elif flag == 2:
				sum = count + (n - 1 - i) * len(s)
			else:
				sum = count
			print(sum)
			f -= 1
main()
